/// The desktop sign-in hop for CodeMie: the CLI's loopback-callback SSO
/// flow, or an injected fake in tests.
typedef FaUiCodeMieSsoFlow =
    Future<CodeMieSsoCredentials?> Function(
      String orgUrl,
      void Function(String) onStatus,
