    this.chatGptOAuthFn = desktopChatGptOAuth,
    this.aiinConnectFn = desktopAiinConnect,
    this.fetchCodeMieModelsFn = fetchCodeMieModels,
    this.modelsFetcher = fetchModelsForEndpoint,
