    expect(
      provider.baseUrl,
      'https://codemie.lab.epam.com/code-assistant-api/v1',
    );
    expect(provider.modelId, 'qwen-coder');
    expect(registry.keyFor(provider.id), 'codemie_access_token=jwt123');
